mapper.select:
select count(distinct vma.id) FROM virtual_warehouse_allocation_detail vmad inner JOIN virtual_warehouse_allocation vma on vma.id = vmad.main_id and vma.is_deleted = false where vmad.is_deleted = false
and vma.status = #{params.status}
${params.permissionSql}

select vmad.sku_id, pd.sku_no, pd.name as productName, vmad.warehouse_id, vmad.warehouse_name, vmad.from_virtual_warehouse_id, vmad.from_virtual_warehouse_name, SUM(coalesce(vmad.qty,0)) as totalQty, SUM(CASE WHEN vwa.status = 'waitSubmit' and vwa.type = 'allocation' THEN vmad.qty else 0 end) as submitAddAllocationQty, SUM(CASE WHEN vwa.status = 'handle' and vwa.type = 'allocation' THEN vmad.qty else 0 end) as handleAddAllocationQty, SUM(CASE WHEN vwa.status = 'waitSubmit' and vwa.type = 'cancel' THEN vmad.qty else 0 end) as submitCancelAllocationQty, SUM(CASE WHEN vwa.status = 'handle' and vwa.type = 'cancel' THEN vmad.qty else 0 end) as handleCancelAllocationQty from virtual_warehouse_allocation vwa inner join virtual_warehouse_allocation_detail vmad on vwa.id = vmad.main_id and vmad.is_deleted = false left join product_detail pd on vmad.sku_id = pd.id and pd.is_deleted = false ${params.sqlMap.default} and vwa.is_deleted = false and vwa.status != 'invalid' and vwa.type != 'transfer'
${params.permissionSql}
group by vmad.sku_id,pd.sku_no,pd.name,vmad.warehouse_id,vmad.warehouse_name,vmad.from_virtual_warehouse_id,vmad.from_virtual_warehouse_name

mapper.sql:
SELECT vma.id, vmad.id as detailId, vma.code, vma.status, vma.type, vma.remark, vmad.sku_id as skuId, vmad.sku_no as skuNo, vmad.product_name as productName, vmad.warehouse_id as warehouseId, vmad.warehouse_name, vmad.from_virtual_warehouse_id as fromVirtualWarehouseId, vmad.from_virtual_warehouse_name, vmad.qty, vmad.to_virtual_warehouse_id as toVirtualWarehouseId, vmad.to_virtual_warehouse_name, vmad.finish_description, vma.invalid_description, vmad.sync_status as syncStatus, vmad.create_user_id, vmad.create_user_name, vmad.create_time, vmad.update_user_id, vmad.update_user_name, vmad.update_time, vmad.third_code as thirdCode, vmad.sys_type, vmad.sys_type_name, vma.remark, vmad.detail_remark detailRemark, vma.is_statistics, COALESCE(iv.realQty,0) - COALESCE(vi.distributionQty,0) as unDistributionQty, case when vmad.to_virtual_warehouse_id = '' then null else COALESCE(vit.toVirtualUsableQty,0) end as toVirtualWarehouseUsableQty, case when vmad.from_virtual_warehouse_id = '' then null else COALESCE(vif.fromVirtualUsableQty,0) end as fromVirtualWarehouseUsableQty, case when vma.status = 'waitSubmit'and vma.type ='allocation' then vmad.qty > COALESCE(iv.realQty,0) - COALESCE(vi.distributionQty,0) when vma.status = 'waitSubmit'and vma.type ='transfer' then vmad.qty > COALESCE(vif.fromVirtualUsableQty,0) when vma.status = 'waitSubmit'and vma.type ='cancel' then vmad.qty > COALESCE(vif.fromVirtualUsableQty,0) else false end isVirtualScarce FROM virtual_warehouse_allocation_detail vmad inner JOIN virtual_warehouse_allocation vma on vma.id = vmad.main_id and vma.is_deleted = false left join ( select sum(qty) as realQty,sku_id,warehouse_id from inventory where is_deleted = false and dict_inventory_status in('usable','frozen') group by sku_id,warehouse_id ) iv on vmad.sku_id = iv.sku_id and vmad.warehouse_id = iv.warehouse_id left join ( select sum(qty) as distributionQty,sku_id,warehouse_id from virtual_inventory where is_deleted = false group by sku_id,warehouse_id ) vi on vmad.sku_id = vi.sku_id and vmad.warehouse_id = vi.warehouse_id left join ( select sum(qty) as toVirtualUsableQty,sku_id,warehouse_id,virtual_warehouse_id from virtual_inventory where is_deleted = false and dict_inventory_status = 'usable' group by sku_id,warehouse_id,virtual_warehouse_id ) vit on vmad.sku_id = vit.sku_id and vmad.warehouse_id = vit.warehouse_id and vmad.to_virtual_warehouse_id = vit.virtual_warehouse_id left join ( select sum(qty) as fromVirtualUsableQty,sku_id,warehouse_id,virtual_warehouse_id from virtual_inventory where is_deleted = false and dict_inventory_status = 'usable' group by sku_id,warehouse_id,virtual_warehouse_id ) vif on vmad.sku_id = vif.sku_id and vmad.warehouse_id = vif.warehouse_id and vmad.from_virtual_warehouse_id = vif.virtual_warehouse_id where ${params.sqlMap.default} and vmad.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
vma.id desc,vmad.id asc
